nChannel(TCA_CHANNEL_5); //TCA.closeChannel(TCA_CHANNEL_5);\n  TCA.openChannel(TCA_CHANNEL_6); //TCA.closeChannel(TCA_CHANNEL_6);\n  TCA.openChannel(TCA_CHANNEL_7); //TCA.closeChannel(TCA_CHANNEL_7); \n\n}\n\nvoid loop()\n{\n\n  uint8_t error, i2cAddress, devCount, unCount;\n\n  SERIAL.println("Scanning...");\n\n  devCount = 0;\n  unCount = 0;\n  for(i2cAddress = 1; i2cAddress < 127; i2cAddress++ )\n  {\n    WIRE.beginTransmission(i2cAddress);\n    error = WIRE.endTransmission();\n\n    if (error == 0)\n    {\n      SERIAL.print("I2C device found at 0x");\n      if (i2cAddress<16) SERIAL.print("0");\n      SERIAL.println(i2cAddress,HEX);\n      devCount++;\n    }\n    else if (error==4)\n    {\n      SERIAL.print("Unknow error at 0x");\n      if (i2cAddress<16) SERIAL.print("0");\n      SERIAL.println(i2cAddress,HEX);\n      unCount++;\n    }    \n  }\n\n  if (devCount + unCount == 0)\n    SERIAL.println("No I2C devices found\\n");\n  else {\n    SERIAL.print(devCount);\n    SERIAL.print(" device(s) found");\n    if (unCount > 0) {\n      SERIAL.print(", and unknown error in ");\n      SERIAL.print(unCount);\n      SERIAL.print(" address");\n    }\n    SERIAL.println();\n  }\n  SERIAL.println();\n  delay(1000); \n}\n'})}),"\n",(0,o.jsxs)(s.ul,{children:["\n",(0,o.jsxs)(s.li,{children:["\n",(0,o.jsxs)(s.p,{children:[(0,o.jsx)(s.strong,{children:"Paso 1"}),' Descarga la biblioteca desde el recurso y a\xf1ade la biblioteca "zip" a tu Arduino IDE. Por favor consulta ',(0,o.jsx)(s.a,{href:"https://wiki.seeedstudio.com/es/How_to_install_Arduino_Library/",children:"C\xf3mo instalar una biblioteca de Arduino"}),"."]}),"\n"]}),"\n",(0,o.jsxs)(s.li,{children:["\n",(0,o.jsxs)(s.p,{children:[(0,o.jsx)(s.strong,{children:"Paso 2"})," Encuentra el c\xf3digo de ejemplo y s\xfabelo a tu placa. Por favor consulta ",(0,o.jsx)(s.a,{href:"https://wiki.seeedstudio.com/es/Upload_Code/",children:"C\xf3mo subir c\xf3digo"}),"."]}),"\n"]}),"\n",(0,o.jsxs)(s.li,{children:["\n",(0,o.jsxs)(s.p